create table if not exists inventory_execution_receipts (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,transaction_id uuid not null references inventory_ledger_transactions(id) on delete restrict,receipt_type text not null check(receipt_type in ('approved','posted','reconciled','reversed')),evidence_hash text not null check(length(evidence_hash)=64),actor_user_id uuid references auth.users(id),created_at timestamptz not null default now(),unique(transaction_id,receipt_type));
create table if not exists inventory_execution_failures (id bigint generated always as identity primary key,business_id uuid not null references businesses(id) on delete cascade,transaction_id uuid references inventory_ledger_transactions(id) on delete restrict,failure_code text not null,failure_hash text not null check(length(failure_hash)=64),created_at timestamptz not null default now());
create index if not exists idx_v21_receipts_business on inventory_execution_receipts(business_id,created_at desc);
create index if not exists idx_v21_failures_business on inventory_execution_failures(business_id,created_at desc);
alter table inventory_execution_receipts enable row level security;
alter table inventory_execution_failures enable row level security;
create policy v21_receipts_select on inventory_execution_receipts for select using(is_member(business_id));
create policy v21_failures_select on inventory_execution_failures for select using(is_member(business_id));
create or replace function public.v21_hash_execution_receipt(p_business_id uuid,p_transaction_id uuid,p_receipt_type text,p_evidence_hash text) returns text language sql immutable as $$ select encode(digest(concat_ws('|',p_business_id::text,p_transaction_id::text,p_receipt_type,p_evidence_hash),'sha256'),'hex') $$;
create or replace function public.v21_record_execution_receipt(p_business_id uuid,p_transaction_id uuid,p_receipt_type text,p_evidence_hash text) returns uuid language plpgsql security definer set search_path=public as $$ declare r uuid; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if length(p_evidence_hash)<>64 or p_evidence_hash !~ '^[0-9a-fA-F]{64}$' then raise exception 'Invalid evidence hash'; end if; if not exists(select 1 from inventory_ledger_transactions where id=p_transaction_id and business_id=p_business_id) then raise exception 'Transaction not found for tenant'; end if; perform pg_advisory_xact_lock(hashtextextended('NABUUMA|INVENTORY_EXECUTION|V2.1',0)); select id into r from inventory_execution_receipts where transaction_id=p_transaction_id and receipt_type=p_receipt_type for update; if r is not null then return r; end if; insert into inventory_execution_receipts(business_id,transaction_id,receipt_type,evidence_hash,actor_user_id) values(p_business_id,p_transaction_id,p_receipt_type,lower(p_evidence_hash),auth.uid()) returning id into r; return r; end; $$;
revoke all on function public.v21_hash_execution_receipt(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.v21_hash_execution_receipt(uuid,uuid,text,text) to authenticated;
revoke all on function public.v21_record_execution_receipt(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.v21_record_execution_receipt(uuid,uuid,text,text) to authenticated;